export default class t{x=0;y=0;constructor(t,e){this.x=t,this.y=e}add(e){return new t(this.x+e.x,this.y+e.y)}subtract(e){return new t(this.x-e.x,this.y-e.y)}multiply(e){return new t(this.x*e,this.y*e)}dot(t){return this.x*t.x+this.y*t.y}magnitude(){return Math.sqrt(this.x*this.x+this.y*this.y)}divide(e){if(!e)throw Error("Cannot divide by zero");return new t(this.x/e,this.y/e)}distance(t){return this.subtract(t).magnitude()}invert(){return new t(-this.x,-this.y)}perpendicular(){return new t(this.y,-this.x)}normalize(){return this.divide(this.magnitude())}absolute(){return new t(Math.abs(this.x),Math.abs(this.y))}angle(){return Math.atan2(this.y,this.x)}isInBoundingBox(t,e){return this.x>=t.x&&this.x<=e.x&&this.y>=t.y&&this.y<=e.y}toArray(){return[this.x,this.y]}copy(){return new t(this.x,this.y)}right(e=1){return this.add(new t(e,0))}left(e=1){return this.add(new t(-e,0))}up(e=1){return this.add(new t(0,-e))}down(e=1){return this.add(new t(0,e))}static right(e=1){return new t(e,0)}static left(e=1){return new t(-e,0)}static up(e=1){return new t(0,-e)}static down(e=1){return new t(0,e)}static zero(){return new t(0,0)}static one(){return new t(1,1)}static min(e,r){return new t(Math.min(e.x,r.x),Math.min(e.y,r.y))}static max(e,r){return new t(Math.max(e.x,r.x),Math.max(e.y,r.y))}static fromPolar(e,r){return new t(r*Math.cos(e),r*Math.sin(e))}static deserializeVectorOnObject(e){return"object"!=typeof e||null===e?e:"number"==typeof e.x&&"number"==typeof e.y?new t(e.x,e.y):Array.isArray(e)?e.map(t.deserializeVectorOnObject):Object.fromEntries(Object.entries(e).map(([e,r])=>[e,t.deserializeVectorOnObject(r)]))}};
